// Static version of dashboard/app.py: filters, KPIs, insights, charts and table run in the browser.
// Data comes from data.js (aggregated counts, generated by dashboard/build_static.py).
(function () {
  "use strict";

  const DATA = window.DASHBOARD_DATA;
  const { dates, airlines: AIRLINES, sentiments: SENTIMENTS, reasons: REASONS, locations: LOCATIONS } = DATA;
  const ROWS = DATA.rows.map(([d, a, s, r, l, n]) => ({ d, a, s, r, l, n }));

  // Colors of the US flag. Old Glory Blue is too dark for data marks,
  // so it is used for the header, accents and text; marks use a brighter flag blue.
  const OLD_GLORY_RED = "#B22234";
  const OLD_GLORY_BLUE = "#3C3B6E";
  const FLAG_BLUE = "#3C5BA9";
  const SILVER = "#A7ABBA";
  const SENTIMENT_COLORS = { negative: OLD_GLORY_RED, neutral: SILVER, positive: FLAG_BLUE };
  const SERIES_COLOR = FLAG_BLUE;

  const SURFACE = "#ffffff";
  const TEXT_PRIMARY = "#1b1a33";
  const TEXT_SECONDARY = "#55566e";
  const TEXT_MUTED = "#6b6c84";
  const GRID = "#e6e7ef";
  const BASELINE = "#c9cbd8";
  const FONT = 'Inter, system-ui, -apple-system, "Segoe UI", sans-serif';
  const PLOT_CONFIG = { displayModeBar: false, responsive: true };

  const fmt = (n) => n.toLocaleString("en-US");
  const pct = (x, digits = 0) => `${x.toFixed(digits)}%`;
  const cap = (s) => s.charAt(0).toUpperCase() + s.slice(1);
  const dayLabel = (iso) =>
    new Date(`${iso}T00:00:00`).toLocaleDateString("en-US", { month: "short", day: "numeric" });
  const shiftDays = (iso, days) => new Date(new Date(`${iso}T00:00:00Z`).getTime() + days * 86400000).toISOString().slice(0, 19).replace("T", " ");
  const fullDate = (iso) =>
    new Date(`${iso}T00:00:00`).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });

  // ------------------------------------------------------------ filter state

  const state = {
    start: dates[0],
    end: dates[dates.length - 1],
    airlines: new Set(AIRLINES),
    sentiments: new Set(SENTIMENTS),
  };

  function filteredRows() {
    const airlineIdx = new Set([...state.airlines].map((a) => AIRLINES.indexOf(a)));
    const sentimentIdx = new Set([...state.sentiments].map((s) => SENTIMENTS.indexOf(s)));
    return ROWS.filter((row) => {
      const date = dates[row.d];
      return date >= state.start && date <= state.end && airlineIdx.has(row.a) && sentimentIdx.has(row.s);
    });
  }

  // ------------------------------------------------------------ aggregation

  function aggregate(rows) {
    const total = rows.reduce((sum, r) => sum + r.n, 0);
    const byAirline = new Map(); // airline -> {negative, neutral, positive}
    const byDate = new Map(); // date -> {negative, neutral, positive}
    const reasons = new Map();
    const locations = new Map();
    let negative = 0;

    for (const r of rows) {
      const airline = AIRLINES[r.a];
      const sentiment = SENTIMENTS[r.s];
      const date = dates[r.d];
      if (!byAirline.has(airline)) byAirline.set(airline, { negative: 0, neutral: 0, positive: 0 });
      byAirline.get(airline)[sentiment] += r.n;
      if (!byDate.has(date)) byDate.set(date, { negative: 0, neutral: 0, positive: 0 });
      byDate.get(date)[sentiment] += r.n;
      if (sentiment === "negative") negative += r.n;
      if (r.r >= 0) reasons.set(REASONS[r.r], (reasons.get(REASONS[r.r]) || 0) + r.n);
      if (r.l >= 0) locations.set(LOCATIONS[r.l], (locations.get(LOCATIONS[r.l]) || 0) + r.n);
    }

    // Fixed airline order (by total volume) so the charts never reshuffle when filtering
    const airlineRows = AIRLINES.filter((a) => byAirline.has(a)).map((a) => {
      const c = byAirline.get(a);
      const sum = c.negative + c.neutral + c.positive;
      return { airline: a, ...c, total: sum };
    });
    const sortDesc = (m) => [...m.entries()].sort((x, y) => y[1] - x[1]);

    return {
      total,
      negative,
      airlineRows,
      dailyRows: dates.filter((d) => byDate.has(d)).map((d) => ({ date: d, ...byDate.get(d) })),
      reasons: sortDesc(reasons),
      locations: sortDesc(locations),
    };
  }

  // ------------------------------------------------------------ charts

  function baseLayout(extra = {}) {
    return {
      height: undefined,
      margin: { l: 8, r: 16, t: 8, b: 8 },
      paper_bgcolor: SURFACE,
      plot_bgcolor: SURFACE,
      font: { family: FONT, color: TEXT_SECONDARY, size: 14 },
      hoverlabel: { bgcolor: "white", bordercolor: BASELINE, font: { family: FONT, color: TEXT_PRIMARY, size: 14 } },
      legend: { orientation: "h", yanchor: "bottom", y: 1.02, x: 0, font: { color: TEXT_SECONDARY } },
      ...extra,
    };
  }

  const axis = (extra = {}) => ({
    gridcolor: GRID, linecolor: BASELINE, zeroline: false, automargin: true,
    tickfont: { color: TEXT_MUTED }, title: { font: { color: TEXT_SECONDARY } }, ...extra,
  });

  function emptyChart(el, message = "No data for this selection") {
    Plotly.react(el, [], baseLayout({
      xaxis: { visible: false }, yaxis: { visible: false },
      annotations: [{ text: message, showarrow: false, font: { color: TEXT_MUTED, size: 15 } }],
    }), PLOT_CONFIG);
  }

  function sentimentByAirline(el, agg) {
    if (!agg.airlineRows.length) return emptyChart(el);
    const names = agg.airlineRows.map((r) => r.airline);
    const traces = SENTIMENTS.filter((s) => agg.airlineRows.some((r) => r[s] > 0)).map((s) => {
      const shares = agg.airlineRows.map((r) => (r[s] / r.total) * 100);
      return {
        type: "bar", orientation: "h", name: cap(s),
        y: names, x: shares,
        marker: { color: SENTIMENT_COLORS[s], line: { color: SURFACE, width: 2 } },
        // Label only segments wide enough to hold the text
        text: shares.map((v) => (v >= 8 ? pct(v) : "")),
        textposition: "inside", insidetextanchor: "middle",
        textfont: { color: s === "neutral" ? TEXT_PRIMARY : "white", size: 13 },
        customdata: agg.airlineRows.map((r) => r[s]),
        hovertemplate: `<b>%{x:.1f}%</b> ${s} · %{customdata:,} tweets<extra>%{y}</extra>`,
      };
    });
    Plotly.react(el, traces, baseLayout({
      barmode: "stack", bargap: 0.38, legend: { ...baseLayout().legend, traceorder: "normal" },
      xaxis: axis({ ticksuffix: "%", range: [0, 100], showgrid: false }),
      yaxis: axis({ autorange: "reversed", showgrid: false, tickfont: { color: TEXT_SECONDARY, size: 14 } }),
    }), PLOT_CONFIG);
  }

  function horizontalBars(el, entries, { emptyMessage, axisTitle, colors, labels, hover }) {
    if (!entries.length) return emptyChart(el, emptyMessage);
    const ordered = [...entries].reverse(); // largest on top
    const max = Math.max(...ordered.map((e) => e[1]));
    Plotly.react(el, [{
      type: "bar", orientation: "h",
      y: ordered.map((e) => e[0]), x: ordered.map((e) => e[1]),
      marker: { color: colors ? colors(ordered) : SERIES_COLOR, line: { color: SURFACE, width: 2 } },
      text: labels(ordered), textposition: "outside", textfont: { color: TEXT_SECONDARY },
      customdata: hover.data ? hover.data(ordered) : undefined,
      hovertemplate: hover.template, cliponaxis: false,
    }], baseLayout({
      bargap: 0.3,
      xaxis: axis({ title: { text: axisTitle, font: { color: TEXT_SECONDARY } }, range: [0, max * 1.15] }),
      yaxis: axis({ showgrid: false, tickfont: { color: TEXT_SECONDARY } }),
    }), PLOT_CONFIG);
  }

  function negativeReasons(el, agg) {
    const sum = agg.reasons.reduce((s, e) => s + e[1], 0);
    const top = agg.reasons.length ? agg.reasons[0][0] : null;
    horizontalBars(el, agg.reasons, {
      emptyMessage: "No negative tweets in this selection",
      axisTitle: "Negative tweets",
      // Emphasis: the top reason in red, the rest in blue
      colors: (ordered) => ordered.map((e) => (e[0] === top ? OLD_GLORY_RED : SERIES_COLOR)),
      labels: (ordered) => ordered.map((e) => pct((e[1] / sum) * 100)),
      hover: {
        data: (ordered) => ordered.map((e) => (e[1] / sum) * 100),
        template: "<b>%{x:,} tweets</b> · %{customdata:.1f}%<extra>%{y}</extra>",
      },
    });
  }

  function topLocations(el, agg) {
    horizontalBars(el, agg.locations.slice(0, 10), {
      axisTitle: "Tweets",
      labels: (ordered) => ordered.map((e) => fmt(e[1])),
      hover: { template: "<b>%{x:,} tweets</b><extra>%{y}</extra>" },
    });
  }

  function tweetsOverTime(el, agg) {
    if (!agg.dailyRows.length) return emptyChart(el);
    const x = agg.dailyRows.map((r) => r.date);
    const present = SENTIMENTS.filter((s) => agg.dailyRows.some((r) => r[s] > 0));
    const traces = present.map((s) => ({
      type: "scatter", mode: "lines+markers", name: cap(s), x, y: agg.dailyRows.map((r) => r[s]),
      line: { color: SENTIMENT_COLORS[s], width: 2 },
      marker: { size: 8, color: SENTIMENT_COLORS[s], line: { color: SURFACE, width: 2 } },
      hovertemplate: `<b>%{y:,}</b> ${s}<extra></extra>`,
    }));

    // Selective direct label: the busiest day of the leading series
    const lead = present.includes("negative") ? "negative" : present[0];
    const peak = agg.dailyRows.reduce((best, r) => (r[lead] > best[lead] ? r : best));
    Plotly.react(el, traces, baseLayout({
      hovermode: "x unified",
      annotations: [{
        x: peak.date, y: peak[lead], text: `<b>Peak</b> · ${fmt(peak[lead])} on ${dayLabel(peak.date)}`,
        showarrow: true, arrowhead: 0, arrowcolor: BASELINE, ax: 0, ay: -28,
        font: { color: TEXT_PRIMARY, size: 13 }, bgcolor: "white", bordercolor: BASELINE, borderpad: 4,
      }],
      xaxis: axis({
        type: "date", showgrid: false, tickformat: "%b %d",
        // Keep the axis on the data range; one tick per day only where there is room for it
        range: [shiftDays(x[0], -0.4), shiftDays(x[x.length - 1], 0.4)],
        dtick: el.clientWidth > 520 ? 86400000 : 2 * 86400000, tickangle: 0,
        showspikes: true, spikemode: "across", spikethickness: 1, spikecolor: BASELINE, spikedash: "solid",
      }),
      yaxis: axis({ title: { text: "Tweets per day", font: { color: TEXT_SECONDARY } }, rangemode: "tozero" }),
    }), PLOT_CONFIG);
  }

  // ------------------------------------------------------------ KPIs & insights

  function setText(id, text) {
    document.getElementById(id).textContent = text;
  }

  function updateKpis(agg) {
    setText("kpi-tweets", fmt(agg.total));
    setText("kpi-negative", agg.total ? pct((agg.negative / agg.total) * 100, 1) : "–");
    setText("kpi-reason", agg.reasons.length ? agg.reasons[0][0] : "–");
    const worst = worstAirline(agg);
    setText("kpi-airline", worst ? `${worst.airline} (${pct(worst.share)})` : "–");
  }

  function worstAirline(agg) {
    if (!agg.negative) return null;
    return agg.airlineRows
      .map((r) => ({ airline: r.airline, share: (r.negative / r.total) * 100 }))
      .reduce((a, b) => (b.share > a.share ? b : a));
  }

  // Body parts: strings are plain text, {b: "..."} is bold – all inserted via textContent
  function insight(icon, title, parts, tone) {
    const box = document.createElement("div");
    box.className = `insight insight-${tone}`;
    const iconEl = document.createElement("div");
    iconEl.className = "insight-icon";
    iconEl.setAttribute("aria-hidden", "true");
    iconEl.textContent = icon;
    const content = document.createElement("div");
    const titleEl = document.createElement("div");
    titleEl.className = "insight-title";
    titleEl.textContent = title;
    const p = document.createElement("p");
    for (const part of parts) {
      if (typeof part === "string") p.append(part);
      else {
        const b = document.createElement("b");
        b.textContent = part.b;
        p.append(b);
      }
    }
    content.append(titleEl, p);
    box.append(iconEl, content);
    return box;
  }

  function buildInsights(agg) {
    if (!agg.total) return [insight("★", "No data", ["Widen the filters to see insights."], "blue")];
    const boxes = [];
    const multipleAirlines = agg.airlineRows.length > 1;

    const worst = worstAirline(agg);
    if (worst && multipleAirlines) {
      const overall = (agg.negative / agg.total) * 100;
      boxes.push(insight("▼", `${worst.airline} draws the most criticism`, [
        { b: pct(worst.share) }, " of its tweets are negative – ",
        { b: `${(worst.share - overall).toFixed(0)} points` }, ` above the average of ${pct(overall)}.`,
      ], "red"));
    }

    if (agg.reasons.length >= 2) {
      const sum = agg.reasons.reduce((s, e) => s + e[1], 0);
      const [first, second] = agg.reasons;
      boxes.push(insight("⚑", `${first[0]} is complaint #1`, [
        { b: pct((first[1] / sum) * 100) }, " of all complaints. Together with ", second[0],
        " it accounts for ", { b: pct(((first[1] + second[1]) / sum) * 100) }, ".",
      ], "red"));
    }

    const negativeDays = agg.dailyRows.filter((r) => r.negative > 0);
    if (negativeDays.length > 1) {
      const peak = negativeDays.reduce((a, b) => (b.negative > a.negative ? b : a));
      const mean = negativeDays.reduce((s, r) => s + r.negative, 0) / negativeDays.length;
      boxes.push(insight("▲", `Complaints spiked on ${dayLabel(peak.date)}`, [
        { b: fmt(peak.negative) }, " negative tweets – ", { b: `${(peak.negative / mean).toFixed(1)}×` },
        " the daily average.",
      ], "blue"));
    }

    if (multipleAirlines && agg.airlineRows.some((r) => r.positive > 0)) {
      const best = agg.airlineRows
        .map((r) => ({ airline: r.airline, share: (r.positive / r.total) * 100 }))
        .reduce((a, b) => (b.share > a.share ? b : a));
      boxes.push(insight("★", `${best.airline} keeps passengers happiest`, [
        "The highest positive share: ", { b: pct(best.share) }, " of its tweets are positive.",
      ], "blue"));
    }

    return boxes.length ? boxes : [insight("★", "Not enough data", ["Select more airlines or sentiments."], "blue")];
  }

  // ------------------------------------------------------------ table

  const COLUMNS = [
    { key: "airline", label: "Airline" },
    { key: "negative", label: "Negative" },
    { key: "neutral", label: "Neutral" },
    { key: "positive", label: "Positive" },
    { key: "total", label: "Total" },
    { key: "negative_share", label: "Negative share (%)" },
  ];
  const sort = { key: null, dir: "descending" };

  function buildTableHeader() {
    const tr = document.querySelector("#summary-table thead tr");
    for (const col of COLUMNS) {
      const th = document.createElement("th");
      th.scope = "col";
      th.dataset.key = col.key;
      const button = document.createElement("button");
      button.type = "button";
      button.textContent = col.label;
      button.addEventListener("click", () => {
        sort.dir = sort.key === col.key && sort.dir === "descending" ? "ascending" : "descending";
        sort.key = col.key;
        render();
      });
      th.append(button);
      tr.append(th);
    }
  }

  function updateTable(agg) {
    let rows = agg.airlineRows.map((r) => ({ ...r, negative_share: (r.negative / r.total) * 100 }));
    if (sort.key) {
      const dir = sort.dir === "ascending" ? 1 : -1;
      rows = rows.sort((a, b) =>
        (typeof a[sort.key] === "string" ? a[sort.key].localeCompare(b[sort.key]) : a[sort.key] - b[sort.key]) * dir);
    }
    for (const th of document.querySelectorAll("#summary-table th")) {
      if (th.dataset.key === sort.key) th.setAttribute("aria-sort", sort.dir);
      else th.removeAttribute("aria-sort");
    }
    const tbody = document.querySelector("#summary-table tbody");
    tbody.replaceChildren(...rows.map((r) => {
      const tr = document.createElement("tr");
      for (const col of COLUMNS) {
        const td = document.createElement("td");
        const value = r[col.key];
        td.textContent = col.key === "airline" ? value : col.key === "negative_share" ? value.toFixed(1) : fmt(value);
        tr.append(td);
      }
      return tr;
    }));
  }

  // ------------------------------------------------------------ filters UI

  function buildFilters() {
    const startInput = document.getElementById("date-start");
    const endInput = document.getElementById("date-end");
    for (const input of [startInput, endInput]) {
      input.min = dates[0];
      input.max = dates[dates.length - 1];
    }
    startInput.addEventListener("change", () => {
      state.start = startInput.value || dates[0];
      if (state.start > state.end) endInput.value = state.end = state.start;
      render();
    });
    endInput.addEventListener("change", () => {
      state.end = endInput.value || dates[dates.length - 1];
      if (state.end < state.start) startInput.value = state.start = state.end;
      render();
    });

    const chips = document.getElementById("airline-filter");
    for (const airline of AIRLINES) {
      const chip = document.createElement("button");
      chip.type = "button";
      chip.className = "chip";
      chip.textContent = airline;
      chip.dataset.airline = airline;
      chip.addEventListener("click", () => {
        if (state.airlines.has(airline)) state.airlines.delete(airline);
        else state.airlines.add(airline);
        // No airline selected means "all airlines"
        if (!state.airlines.size) AIRLINES.forEach((a) => state.airlines.add(a));
        render();
      });
      chips.append(chip);
    }

    const checklist = document.getElementById("sentiment-filter");
    for (const sentiment of SENTIMENTS) {
      const label = document.createElement("label");
      const input = document.createElement("input");
      input.type = "checkbox";
      input.value = sentiment;
      input.addEventListener("change", () => {
        if (input.checked) state.sentiments.add(sentiment);
        else state.sentiments.delete(sentiment);
        render();
      });
      label.append(input, ` ${cap(sentiment)}`);
      checklist.append(label);
    }

    document.getElementById("reset").addEventListener("click", () => {
      state.start = dates[0];
      state.end = dates[dates.length - 1];
      state.airlines = new Set(AIRLINES);
      state.sentiments = new Set(SENTIMENTS);
      sort.key = null;
      render();
    });
  }

  function syncFilterControls() {
    document.getElementById("date-start").value = state.start;
    document.getElementById("date-end").value = state.end;
    for (const chip of document.querySelectorAll(".chip")) {
      chip.setAttribute("aria-pressed", String(state.airlines.has(chip.dataset.airline)));
    }
    for (const input of document.querySelectorAll("#sentiment-filter input")) {
      input.checked = state.sentiments.has(input.value);
    }
  }

  // ------------------------------------------------------------ render

  function render() {
    syncFilterControls();
    const agg = aggregate(filteredRows());
    updateKpis(agg);
    document.getElementById("insights").replaceChildren(...buildInsights(agg));
    sentimentByAirline(document.getElementById("chart-sentiment"), agg);
    negativeReasons(document.getElementById("chart-reasons"), agg);
    tweetsOverTime(document.getElementById("chart-time"), agg);
    topLocations(document.getElementById("chart-locations"), agg);
    updateTable(agg);
  }

  const totalTweets = ROWS.reduce((s, r) => s + r.n, 0);
  setText("subtitle", `How ${fmt(totalTweets)} travelers talked about six US airlines on Twitter · ` +
    `${dayLabel(dates[0])} – ${fullDate(dates[dates.length - 1])}`);
  buildFilters();
  buildTableHeader();
  render();

  // Re-render after resizing so the tick density matches the new width
  let resizeTimer;
  window.addEventListener("resize", () => {
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(render, 200);
  });
})();
